{
  "actions": [
    {
      "action": "Separate requested pickups from stock-backed commitments",
      "mechanism": "Expected returns support tentative requests; only inspected, available items can back a confirmed pickup.",
      "implementation": "Track out-on-loan, awaiting-inspection, available, and allocated states. Atomically assign one available item before confirming; display tentative requests explicitly.",
      "check": "Simulate overdue returns and simultaneous bookings; no confirmation should lack an exclusive allocation of inspected stock.",
      "risk": "Future bookings become less certain; explain their status clearly."
    },
    {
      "action": "Give every threatened reservation an owned recovery case",
      "mechanism": "An overdue return triggers explicit resolution rather than leaving affected borrowers with an unchanged pickup expectation.",
      "implementation": "Identify dependent requests, assign a staff owner and decision deadline, and offer substitution, rescheduling, or withdrawal through each borrower's existing contact preference.",
      "check": "Inject an overdue event; every affected request must receive a case, owner, deadline, and recorded next step.",
      "risk": "Unanswered contact must remain unresolved, not count as consent."
    },
    {
      "action": "Request consent for a specific inspected substitute",
      "mechanism": "Item-level offers expose condition and accessory differences before borrowers decide whether an alternative meets their needs.",
      "implementation": "Send an inspected substitute's differences through the supplied contact preference. Hold it briefly; allocate only after explicit acceptance. Reoffer if the proposed item changes.",
      "check": "Reject and ignore test offers; neither may change the assigned item. Accepted offers must match the disclosed item.",
      "risk": "Expiring holds can frustrate borrowers who respond slowly."
    },
    {
      "action": "Match alternatives across all affected reservations",
      "mechanism": "Batch matching preserves scarce accessory combinations instead of letting the first recovery consume another borrower's only suitable option.",
      "implementation": "Match inspected stock against recorded requirements, using pickup deadlines and original request order. Create exclusive offers; require consent for every substitution.",
      "check": "Test two borrowers where only one needs a particular accessory; the matching must preserve that feasible pairing without double-offering stock.",
      "risk": "Incomplete requirements can make apparently feasible matches unusable."
    },
    {
      "action": "Prioritize return inspections by threatened pickup deadlines",
      "mechanism": "Inspection queues direct existing staff attention toward returned items that could resolve imminent shortages without bypassing safety checks.",
      "implementation": "Link awaiting-inspection items to affected requests. Sort by pickup deadline, retain the full checklist, and record accessory completeness before availability changes.",
      "check": "Return a needed item with a missing accessory; it must remain unavailable until inspection finishes and its limitations are recorded.",
      "risk": "Urgent requests could starve routine inspections; monitor queue age."
    },
    {
      "action": "Add measured turnaround gaps to request scheduling",
      "mechanism": "Explicit return-and-inspection gaps reduce reliance on immediate handoffs while preserving stock-backed confirmation rules.",
      "implementation": "Use existing return and inspection timestamps to set provisional gaps by tool category. Offer later tentative windows rather than silently rejecting tight requests.",
      "check": "Compare threatened pickups and waiting times before and after changes; inspect cancellations and refused requests alongside any apparent improvement.",
      "risk": "Oversized gaps reduce access without necessarily preventing failures."
    },
    {
      "action": "Audit failed pickups against an immutable request cohort",
      "mechanism": "Keeping original requests in the denominator prevents cancellations and rescheduling from disguising service failures.",
      "implementation": "Record original windows, cancellations, shifts, outcomes, inspected-stock snapshots, and consent events. Audit failures for feasible stock-backed recovery using information available before pickup.",
      "check": "Cancel a difficult test booking; it must remain in cohort reporting. Count preventability only when a feasible recovery is evidenced.",
      "risk": "Unknown consent makes some failures indeterminate; report those separately."
    }
  ],
  "abstention_reason": ""
}
